use std::rc::Rc;use std::cell::RefCell;use std::collections::VecDeque;impl Solution{pub fn level_order_bottom(root:Option<Rc<RefCell<TreeNode>>>)->Vec<Vec<i32>>{let mut o=vec![];let mut q=VecDeque::new();if let Some(r)=root{q.push_back(r)}else{return o}while !q.is_empty(){let n=q.len();let mut v=vec![];for _ in 0..n{let x=q.pop_front().unwrap();let b=x.borrow();v.push(b.val);if let Some(l)=b.left.clone(){q.push_back(l)}if let Some(r)=b.right.clone(){q.push_back(r)}}o.push(v);}o.reverse();o}}
